// src/components/DataTableGroup/DataTableGroup.js
import React from 'react';

const DataTableGroup = ({ options, onGroupChange }) => {
    return (
        <select onChange={(e) => onGroupChange(e.target.value)}>
            {options.map((option) => (
                <option key={option.value} value={option.value}>
                    {option.label}
                </option>
            ))}
        </select>
    );
};

export default DataTableGroup;
```

